    /// A long paragraph with a 1 × 0.5 in floating image 1.5 in into the
    /// column, 0.25 in below the paragraph top, in `wrap` mode.
    fn wrapped_image_doc(wrap: engine::WrapKind, v_frame: engine::VRelativeFrom) -> DocumentTree {
        let body = "Wrapped text flows on both sides of the picture while the \
                    paragraph continues for several more lines of prose. "
            .repeat(6);
        let mut doc = DocumentTree::from_text(&format!("\u{FFFC}{body}"));
        if let Some(p) = doc.blocks[0].as_paragraph_mut() {
            p.inline_objects.push(engine::InlineObject {
                at: 0,
                kind: engine::InlineKind::Image {
                    rel_id: "nge_float_1".to_string(),
                    width_emu: 914_400,
                    height_emu: 457_200,
                },
                anchor: Some(Box::new(engine::FloatAnchor {
                    position_h: engine::HPosition {
                        relative_from: engine::HRelativeFrom::Column,
                        offset: engine::FloatOffset::Emu(1_371_600),
                    },
                    position_v: engine::VPosition {
                        relative_from: v_frame,
                        offset: engine::FloatOffset::Emu(228_600),
                    },
                    dist_left_emu: 114_300,
                    dist_right_emu: 114_300,
                    wrap,
                    ..engine::FloatAnchor::default()
                })),
                source_xml: None,
            });
        }
        doc
    }

    /// Square wrap cuts the bands the image overlaps into two segments;
    /// the two lines of a band share `y_top`, and a click over either
    /// segment lands in THAT segment's line (the per-segment hit rect).
    #[test]
    fn square_wrap_cuts_bands_and_hit_tests_per_segment() {
        let engine = test_engine_with_doc(wrapped_image_doc(
            engine::WrapKind::Square,
            engine::VRelativeFrom::Paragraph,
        ));
        let (pages, _, _, info) = engine.build_pages(2.0, false, None).expect("layout");
        assert!(info.degradations.is_empty(), "{:?}", info.degradations);
        let para = pages[0].blocks[0].as_paragraph().expect("paragraph");
        assert!(
            para.lines.iter().any(|l| l.segments.len() == 2),
            "some band is cut in two"
        );
        let geom = engine.document_geometry().expect("geom");
        let (left, right) = geom
            .iter()
            .enumerate()
            .find_map(|(i, g)| {
                let n = geom.get(i + 1)?;
                (n.y_top == g.y_top && n.hit_left > g.hit_left + g.hit_width).then_some((g, n))
            })
            .expect("a band with two segment lines");
        assert!(
            right.start_byte >= left.end_byte,
            "reading order = source order"
        );
        let y = left.y_top + left.height / 2.0;
        let hit_l = hit_test_geom(&geom, left.hit_left + 2.0, y);
        assert!(hit_l.offset >= left.start_byte && hit_l.offset <= left.end_byte);
        let hit_r = hit_test_geom(&geom, right.hit_left + right.hit_width - 2.0, y);
        assert!(
            hit_r.offset >= right.start_byte && hit_r.offset <= right.end_byte,
            "{hit_r:?} not in [{}, {}]",
            right.start_byte,
            right.end_byte
        );
        /* The image's own rect sits in the gap between the segments. */
        let img = &engine.image_geometry().expect("images")[0];
        assert_eq!(img.wrap, Some(bridge::ImageWrapMode::Square));
        assert!(img.rect.x >= left.hit_left + left.hit_width - 0.5);
        assert!(img.rect.x + img.rect.w <= right.hit_left + 0.5);
        /* Pinned: a change here moves the wrap goldens. */
        let fp = layout::geometry_fingerprint(&pages);
        if std::env::var_os("NGE_PRINT_WRAP_FINGERPRINTS").is_some() {
            eprintln!("ENGINE WRAP FINGERPRINT square_x2 = {fp:#x}");
        }
        assert_eq!(fp, PINNED_SQUARE_WRAP_X2);
    }

    const PINNED_SQUARE_WRAP_X2: u64 = 0xe26a96b1e1df3649;

    /* ------------------------ Issue #83 — text boxes ------------------------ */

    /// Two floating text boxes with square wrap: an LTR box at the left of
    /// the first (LTR) paragraph's column, and an RTL box aligned right in
    /// the second (RTL, Arabic) paragraph.
    fn text_box_doc() -> DocumentTree {
        let prose = "Body text wraps around the framed story while the paragraph \
                     keeps going for several more lines of ordinary prose. "
            .repeat(5);
        let arabic = "هذا نص عربي يلتف حول صندوق النص على اليمين ويستمر لعدة أسطر أخرى. ".repeat(5);
        let para = |text: &str, rtl: bool| {
            engine::Block::Paragraph(engine::Paragraph {
                text: text.to_string(),
                props: engine::ParaProperties {
                    direction: rtl.then_some(engine::TextDirection::Rtl),
                    ..Default::default()
                },
                ..Default::default()
            })
        };
        let doc = DocumentTree::from_blocks(vec![para(&prose, false), para(&arabic, true)]);
        let story = |text: &str, rtl: bool| vec![para(text, rtl)];
        let (doc, h0, a0) = doc.insert_text_box_at(
            EnginePos {
                path: EngineBlockPath::top(0),
                offset: 0,
            },
            1_371_600,
            685_800,
        );
        let doc = doc.with_updated_text_box(&h0, a0, story("Box one frames a short story.", false));
        let (doc, h1, a1) = doc.insert_text_box_at(
            EnginePos {
                path: EngineBlockPath::top(1),
                offset: 0,
            },
            1_371_600,
            685_800,
        );
        let mut doc = doc.with_updated_text_box(&h1, a1, story("صندوق نص من اليمين", true));
        if let Some(engine::Block::Paragraph(p)) = doc.blocks.get_mut(1)
            && let Some(a) = p.inline_objects[0].anchor.as_mut()
        {
            a.position_h.offset = engine::FloatOffset::Align(engine::FloatAlign::Right);
        }
        doc
    }

    fn text_box_engine() -> Engine {
        let mut engine = test_engine_with_doc(text_box_doc());
        let bytes = include_bytes!("../../../ts/fonts/NotoNaskhArabic-Regular.ttf").to_vec();
        let font = LoadedFont::parse("test-arabic".to_string(), bytes).expect("arabic font");
        engine
            .fonts
            .insert("test-arabic".to_string(), Arc::new(font));
        engine
    }

    /// Both boxes resolve to floats carrying a laid-out story; the body
    /// text wraps around them (square wrap cuts its bands); the RTL story
    /// lays out right-to-left; the scene paints fill, clipped story and
    /// outline; the PDF exporter accepts the frames. Geometry pinned.
    #[test]
    fn text_boxes_lay_out_their_stories_and_wrap_body_text() {
        let engine = text_box_engine();
        let (pages, fonts, _, info) = engine.build_pages(1.0, false, None).expect("layout");
        assert!(info.degradations.is_empty(), "{:?}", info.degradations);
        let boxes: Vec<&layout::FloatBox> = pages
            .iter()
            .flat_map(|p| p.floats.iter())
            .filter(|f| f.text_box.is_some())
            .collect();
        assert_eq!(boxes.len(), 2, "two text box floats");
        for f in &boxes {
            let tb = f.text_box.as_deref().expect("frame");
            let p = tb.blocks[0].as_paragraph().expect("story paragraph");
            assert!(!p.lines.is_empty() && !p.lines[0].runs.is_empty());
            let (origin, size) = f.text_box_content_rect().expect("content rect");
            assert!(
                origin.x > f.origin.x && size.width < f.size.width,
                "insets applied"
            );
        }
        let rtl = boxes[1].text_box.as_deref().expect("rtl frame");
        assert_eq!(
            rtl.blocks[0].as_paragraph().expect("p").direction,
            ShapingDirection::Rtl
        );
        /* The right-aligned box sits at the column's right edge. */
        let page = &pages[0];
        let right_edge = page.size.width - page.margins.right;
        assert!((boxes[1].origin.x + boxes[1].size.width - right_edge).abs() < 0.5);
        /* Square wrap: the first paragraph's bands beside the left box
        start to the right of it. */
        let p0 = page.blocks[0].as_paragraph().expect("p0");
        assert!(
            p0.lines.iter().any(|l| l
                .segments
                .first()
                .is_some_and(|s| s.x0 >= boxes[0].size.width)),
            "some band starts right of the left box"
        );
        /* Scene: fill + outline + a clipped story per box. */
        let scene = render::scene::build_document_scene(&pages, 0.0);
        let clips = scene
            .cmds
            .iter()
            .filter(|c| matches!(c, render::scene::DisplayCmd::PushClip { .. }))
            .count();
        assert_eq!(clips, 2);
        let strokes = scene
            .cmds
            .iter()
            .filter(|c| matches!(c, render::scene::DisplayCmd::StrokeRect { .. }))
            .count();
        assert!(strokes >= 2);
        let mut pdf = Vec::new();
        format_pdf::export_pdf(&pages, &fonts, &[], format_pdf::PdfProfile::Plain, &mut pdf)
            .expect("pdf");
        assert!(pdf.starts_with(b"%PDF"));
        /* Pinned: a change here moves the text-box goldens. */
        let fp = layout::geometry_fingerprint(&pages);
        if std::env::var_os("NGE_PRINT_WRAP_FINGERPRINTS").is_some() {
            eprintln!("ENGINE TEXT BOX FINGERPRINT = {fp:#x}");
        }
        assert_eq!(fp, PINNED_TEXT_BOXES_X1);
    }

    const PINNED_TEXT_BOXES_X1: u64 = 0x36dc281bfc45e4a1;

    /// An overflowing story is clipped at the shape's bottom edge (lines
    /// past it are culled from the scene) and a centred story shifts down
    /// by half the spare height.
    #[test]
    fn text_box_story_valign_and_overflow_clip() {
        let mut doc = text_box_doc();
        let host = EngineBlockPath::top(0);
        let long: Vec<engine::Block> = (0..12)
            .map(|i| {
                engine::Block::Paragraph(engine::Paragraph {
                    text: format!("overflow line {i}"),
                    ..Default::default()
                })
            })
            .collect();
        doc = doc.with_updated_text_box(&host, 0, long);
        let engine = text_box_engine();
        let mut engine = engine;
        engine.undo = UndoStack::new(doc.clone(), 100);
        let (pages, _, _, _) = engine.build_pages(1.0, false, None).expect("layout");
        let f = pages[0]
            .floats
            .iter()
            .find(|f| f.text_box.is_some())
            .expect("box");
        let tb = f.text_box.as_deref().expect("frame");
        assert_eq!(tb.blocks.len(), 12, "every story block is laid out");
        let scene = render::scene::build_document_scene(&pages[..1], 0.0);
        let painted_runs = scene
            .cmds
            .iter()
            .filter(|c| matches!(c, render::scene::DisplayCmd::DrawGlyphRun(_)))
            .count();
        let runs_in = |blocks: &[LayoutBlock]| -> usize {
            blocks
                .iter()
                .filter_map(LayoutBlock::as_paragraph)
                .map(|p| p.lines.iter().map(|l| l.runs.len()).sum::<usize>())
                .sum()
        };
        let every_run = runs_in(&pages[0].blocks)
            + pages[0]
                .floats
                .iter()
                .filter_map(|g| g.text_box.as_deref())
                .map(|t| runs_in(&t.blocks))
                .sum::<usize>();
        assert!(painted_runs < every_run, "overflowing lines are culled");

        /* Centre a one-line story: its block shifts down. */
        let mut doc = text_box_doc();
        if let Some(engine::Block::Paragraph(p)) = doc.blocks.get_mut(0)
            && let engine::InlineKind::TextBox { story, .. } = &mut p.inline_objects[0].kind
        {
            story.v_align = engine::TextBoxVAlign::Center;
            story.body = vec![engine::Block::Paragraph(engine::Paragraph {
                text: "Hi".into(),
                ..Default::default()
            })];
        }
        engine.undo = UndoStack::new(doc, 100);
        let (pages, _, _, _) = engine.build_pages(1.0, false, None).expect("layout");
        let f = pages[0]
            .floats
            .iter()
            .find(|f| f.text_box.is_some())
            .expect("box");
        let tb = f.text_box.as_deref().expect("frame");
        let (_, inner) = f.text_box_content_rect().expect("rect");
        let b = &tb.blocks[0];
        let spare = inner.height - b.size().height;
        assert!(spare > 1.0);
        assert!((b.origin().y - spare / 2.0).abs() < 0.01);
    }

    /* ------------------ Issue #165 — nested text boxes + a11y ------------------ */

    fn plain_para(text: &str) -> engine::Block {
        engine::Block::Paragraph(engine::Paragraph {
            text: text.to_string(),
            ..Default::default()
        })
    }

    /// Give the text box anchored at `(host, at)` a `<wp:docPr>`.
    fn name_text_box(doc: &mut DocumentTree, host: usize, doc_pr: &str) {
        if let Some(engine::Block::Paragraph(p)) = doc.blocks.get_mut(host)
            && let Some(a) = p.inline_objects[0].anchor.as_mut()
        {
            a.doc_pr_xml = Some(doc_pr.to_string());
        }
    }

    /// A body paragraph hosting a 3" × 2" floating box ("Sidebar") whose
    /// story hosts a 0.75" × 0.5" floating box ("Inner", square wrap) at
    /// the head of a long outer-story paragraph — the two-level nesting
    /// the `.docx` reader models.
    fn nested_text_box_doc() -> DocumentTree {
        let outer_text = "Outer story text wraps beside the nested box. ".repeat(2);
        let mut story = DocumentTree::from_blocks(vec![plain_para(&outer_text)]);
        let (s2, h, a) = story.insert_text_box_at(
            EnginePos {
                path: EngineBlockPath::top(0),
                offset: 0,
            },
            1_371_600,
            548_640,
        );
        story = s2.with_updated_text_box(&h, a, vec![plain_para("Inner story")]);
        name_text_box(&mut story, 0, r#"<wp:docPr id="7" name="Inner"/>"#);
        let outer_body: Vec<engine::Block> = story.blocks.iter().cloned().collect();

        let prose = "Body text wraps around the sidebar box and keeps going. ".repeat(6);
        let doc = DocumentTree::from_blocks(vec![plain_para(&prose), plain_para("Tail")]);
        let (doc, h0, a0) = doc.insert_text_box_at(
            EnginePos {
                path: EngineBlockPath::top(0),
                offset: 0,
            },
            2_743_200,
            2_743_200,
        );
        let mut doc = doc.with_updated_text_box(&h0, a0, outer_body);
        name_text_box(
            &mut doc,
            0,
            r#"<wp:docPr id="5" name="Sidebar" descr="Pull quote &amp; notes"/>"#,
        );
        doc
    }

    /// The nested box resolves as a float of its parent's story: laid
    /// out inside the parent's content rect with its own story, the
    /// parent story wraps around it, the scene paints (and clips) both
    /// boxes, the PDF exporter walks both stories. Geometry pinned.
    #[test]
    fn nested_text_boxes_lay_out_wrap_and_paint() {
        let engine = test_engine_with_doc(nested_text_box_doc());
        let (pages, fonts, _, info) = engine.build_pages(1.0, false, None).expect("layout");
        assert!(info.degradations.is_empty(), "{:?}", info.degradations);
        let outer = pages[0]
            .floats
            .iter()
            .find(|f| f.text_box.is_some())
            .expect("outer box");
        let otb = outer.text_box.as_deref().expect("outer frame");
        assert_eq!(otb.floats.len(), 1, "one nested box resolved");
        let inner = &otb.floats[0];
        let itb = inner.text_box.as_deref().expect("nested frame");
        assert!(itb.floats.is_empty());
        let ip = itb.blocks[0]
            .as_paragraph()
            .expect("nested story paragraph");
        assert!(!ip.lines.is_empty() && !ip.lines[0].runs.is_empty());
        /* Inside the parent's content rect (content-relative origin). */
        let (_, inner_rect) = outer.text_box_content_rect().expect("content rect");
        assert!(inner.origin.x >= -0.01 && inner.origin.y >= -0.01);
        assert!(inner.origin.x + inner.size.width <= inner_rect.width + 0.5);
        /* Square wrap: the outer story's lines beside the nested box
        start right of it. */
        let op = otb.blocks[0].as_paragraph().expect("outer story paragraph");
        assert!(
            op.lines
                .iter()
                .any(|l| l.segments.first().is_some_and(|s| s.x0 >= inner.size.width)),
            "some outer-story band starts right of the nested box"
        );
        /* Scene: both boxes clip + stroke; the nested story paints. */
        let scene = render::scene::build_document_scene(&pages, 0.0);
        let clips = scene
            .cmds
            .iter()
            .filter(|c| matches!(c, render::scene::DisplayCmd::PushClip { .. }))
            .count();
        assert_eq!(clips, 2, "outer + nested clip");
        let strokes = scene
            .cmds
            .iter()
            .filter(|c| matches!(c, render::scene::DisplayCmd::StrokeRect { .. }))
            .count();
        assert!(strokes >= 2);
        let runs_in = |blocks: &[LayoutBlock]| -> usize {
            blocks
                .iter()
                .filter_map(LayoutBlock::as_paragraph)
                .map(|p| p.lines.iter().map(|l| l.runs.len()).sum::<usize>())
                .sum()
        };
        let painted_runs = scene
            .cmds
            .iter()
            .filter(|c| matches!(c, render::scene::DisplayCmd::DrawGlyphRun(_)))
            .count();
        /* The fixture's stories fit their boxes (nothing is culled). */
        let bottom = |blocks: &[LayoutBlock]| {
            blocks
                .iter()
                .map(|b| b.origin().y + b.size().height)
                .fold(0.0_f32, f32::max)
        };
        assert!(bottom(&otb.blocks) <= inner_rect.height);
        let (_, nested_rect) = inner.text_box_content_rect().expect("nested rect");
        assert!(bottom(&itb.blocks) <= nested_rect.height + 0.5);
        assert!(
            painted_runs >= runs_in(&pages[0].blocks) + runs_in(&otb.blocks) + runs_in(&itb.blocks),
            "body, outer and nested story runs all paint"
        );
        let mut pdf = Vec::new();
        format_pdf::export_pdf(&pages, &fonts, &[], format_pdf::PdfProfile::Plain, &mut pdf)
            .expect("pdf");
        assert!(pdf.starts_with(b"%PDF"));
        let Event::PdfExported { bytes, .. } = engine.do_export_pdf(PdfConformance::A2u) else {
            panic!("engine pdf export");
        };
        assert!(bytes.starts_with(b"%PDF"));
        /* Pinned: a change here moves the nested-box geometry. */
        let fp = layout::geometry_fingerprint(&pages);
        if std::env::var_os("NGE_PRINT_WRAP_FINGERPRINTS").is_some() {
            eprintln!("ENGINE NESTED TEXT BOX FINGERPRINT = {fp:#x}");
        }
        assert_eq!(fp, PINNED_NESTED_TEXT_BOXES);
    }

    const PINNED_NESTED_TEXT_BOXES: u64 = 0x0effc1fd111fcc44;

    /// Issue #197 — a 0.75" × 0.5" square-wrapped floating picture
    /// anchored at the head of a story paragraph.
    fn story_float_image(rel: &str) -> engine::InlineObject {
        engine::InlineObject {
            at: 0,
            kind: engine::InlineKind::Image {
                rel_id: rel.to_string(),
                width_emu: 685_800,
                height_emu: 457_200,
            },
            anchor: Some(Box::new(engine::FloatAnchor {
                dist_right_emu: 57_150,
                wrap: engine::WrapKind::Square,
                ..engine::FloatAnchor::default()
            })),
            source_xml: None,
        }
    }

    /// Issue #197 — a body paragraph hosting a 3" × 2" floating box whose
    /// story opens with a floating picture (square wrap) followed by a
    /// long run of prose; the picture's bytes live in the document media.
    fn boxed_float_image_doc() -> DocumentTree {
        let story_text = format!(
            "\u{FFFC}{}",
            "Story text wraps beside the picture inside the box. ".repeat(3)
        );
        let mut story = DocumentTree::from_text(&story_text);
        if let Some(p) = story.blocks[0].as_paragraph_mut() {
            p.inline_objects.push(story_float_image("rIdBoxPic"));
        }
        let story_body: Vec<engine::Block> = story.blocks.iter().cloned().collect();
        let prose = "Body text wraps around the framed picture box. ".repeat(6);
        let doc = DocumentTree::from_blocks(vec![plain_para(&prose), plain_para("Tail")]);
        let (doc, h0, a0) = doc.insert_text_box_at(
            EnginePos {
                path: EngineBlockPath::top(0),
                offset: 0,
            },
            2_743_200,
            1_828_800,
        );
        let mut doc = doc.with_updated_text_box(&h0, a0, story_body);
        doc.media.insert(
            "rIdBoxPic".into(),
            engine::ImageBlob {
                content_type: "image/jpeg".to_string(),
                data: format_pdf::test_images::jpeg(24, 16, 3),
            },
        );
        doc
    }

    /// Issue #197 — a floating picture anchored in a text-box story is a
    /// float of the box's content rect: it resolves into the frame's
    /// `floats`, the story wraps around it (square wrap), the scene draws
    /// it inside the box clip, and the PDF embeds + paints it. Pinned.
    #[test]
    fn floating_picture_in_text_box_story_wraps_and_paints() {
        let engine = test_engine_with_doc(boxed_float_image_doc());
        let (pages, _, _, info) = engine.build_pages(1.0, false, None).expect("layout");
        assert!(info.degradations.is_empty(), "{:?}", info.degradations);
        let outer = pages[0]
            .floats
            .iter()
            .find(|f| f.text_box.is_some())
            .expect("box float");
        let tb = outer.text_box.as_deref().expect("frame");
        assert_eq!(tb.floats.len(), 1, "the story picture resolves");
        let pic = &tb.floats[0];
        assert!(pic.text_box.is_none());
        assert_eq!(pic.rel_id, "rIdBoxPic");
        let (origin, content) = outer.text_box_content_rect().expect("content rect");
        assert!(pic.origin.x >= -0.01 && pic.origin.y >= -0.01);
        assert!(pic.origin.x + pic.size.width <= content.width + 0.5);
        assert!((pic.size.width - 54.0).abs() < 0.5, "0.75in = 54pt");
        /* Square wrap: story lines beside the picture start right of it. */
        let sp = tb.blocks[0].as_paragraph().expect("story paragraph");
        assert!(
            sp.lines
                .iter()
                .any(|l| l.segments.first().is_some_and(|s| s.x0 >= pic.size.width)),
            "some story band starts right of the picture"
        );
        /* Scene: the picture draws inside the box clip, at the content
        origin + its content-relative offset (page float origins are
        page-relative, so no extra base on page 0). */
        let scene = render::scene::build_document_scene(&pages, 0.0);
        let cmds = &scene.cmds;
        let clip = cmds
            .iter()
            .position(|c| matches!(c, render::scene::DisplayCmd::PushClip { .. }))
            .expect("box clip");
        let draw = cmds
            .iter()
            .position(|c| {
                matches!(c, render::scene::DisplayCmd::DrawImage { rel_id, .. } if rel_id == "rIdBoxPic")
            })
            .expect("story picture paints");
        let pop = cmds
            .iter()
            .position(|c| matches!(c, render::scene::DisplayCmd::PopClip))
            .expect("pop");
        assert!(clip < draw && draw < pop, "inside the box clip");
        if let render::scene::DisplayCmd::DrawImage { rect, .. } = &cmds[draw] {
            let want_x = f64::from(origin.x + pic.origin.x);
            let want_y = f64::from(origin.y + pic.origin.y);
            assert!((rect.x0 - want_x).abs() < 0.01, "{} vs {want_x}", rect.x0);
            assert!((rect.y0 - want_y).abs() < 0.01, "{} vs {want_y}", rect.y0);
        }
        /* PDF: the picture is embedded and painted. */
        let Event::PdfExported { bytes, .. } = engine.do_export_pdf(PdfConformance::A2u) else {
            panic!("engine pdf export");
        };
        let count = |needle: &[u8]| bytes.windows(needle.len()).filter(|w| *w == needle).count();
        assert_eq!(count(b"/Subtype /Image"), 1, "story picture embedded");
        let fp = layout::geometry_fingerprint(&pages);
        if std::env::var_os("NGE_PRINT_WRAP_FINGERPRINTS").is_some() {
            eprintln!("ENGINE BOXED FLOAT IMAGE FINGERPRINT = {fp:#x}");
        }
        assert_eq!(fp, PINNED_BOXED_FLOAT_IMAGE);
    }

    const PINNED_BOXED_FLOAT_IMAGE: u64 = 0xce020097437da437;

    /// Issue #196 — the committed `text_boxes_nested.docx` (outer box at
    /// 1", 3" on the page, 3" × 2"; nested box 1" / 0.5" into its
    /// content rect, 1.5" × 0.6"): a press at the geometry the e2e spec
    /// uses enters the nested story, a press lower in the outer box its
    /// story. Pins the e2e's coordinate assumptions natively.
    #[test]
    fn nested_text_box_fixture_routes_presses_by_geometry() {
        let bytes = include_bytes!("../../format-docx/tests/fixtures/text_boxes_nested.docx");
        let archive = format_docx::read_docx(bytes).expect("fixture");
        let mut engine = test_engine_with_doc(archive.document);
        let scale = engine.scale();
        let px = |inches: f32| inches * 72.0 * scale;
        let at = |x: f32, y: f32| BridgePoint { x: px(x), y: px(y) };
        let evt = engine.do_place_caret_at_point(0, at(2.85, 3.8));
        let Event::SelectionChanged { editing_story, .. } = &evt else {
            panic!("{evt:?}");
        };
        assert_eq!(
            editing_story.as_ref().map(|s| s.rid.as_str()),
            Some("1@0/1@0")
        );
        let evt = engine.do_place_caret_at_point(0, at(1.5, 4.6));
        let Event::SelectionChanged { editing_story, .. } = &evt else {
            panic!("{evt:?}");
        };
        assert_eq!(editing_story.as_ref().map(|s| s.rid.as_str()), Some("1@0"));
    }

    /// Issue #196 — page-space `(x, y, w, h)` of the outer box of
    /// [`nested_text_box_doc`] and of the box nested in its story.
    /// `(x, y, w, h)` in page space.
    type BoxRect = (f32, f32, f32, f32);

    fn nested_box_rects(engine: &Engine) -> (BoxRect, BoxRect) {
        let _ = engine.document_geometry().expect("layout");
        let snap_cell = engine.layout_snapshot.borrow();
        let snap = snap_cell.as_ref().expect("snapshot");
        let f = snap.pages[0]
            .floats
            .iter()
            .find(|f| f.text_box.is_some())
            .expect("outer box");
        let (co, _) = f.text_box_content_rect().expect("content rect");
        let nf = &f.text_box.as_deref().expect("frame").floats[0];
        (
            (f.origin.x, f.origin.y, f.size.width, f.size.height),
            (
                co.x + nf.origin.x,
                co.y + nf.origin.y,
                nf.size.width,
                nf.size.height,
            ),
        )
    }

    fn nested_story_text(engine: &Engine) -> String {
        let doc = engine.undo.current();
        text_box_story_blocks(
            doc,
            &EngineBlockPath::top(0),
            0,
            Some(&(EngineBlockPath::top(0), 0)),
        )
        .and_then(|b| {
            b.first()
                .and_then(|b| b.as_paragraph())
                .map(|p| p.text.clone())
        })
        .unwrap_or_default()
    }

    /// Issue #196 — a press inside a NESTED box enters the nested story
    /// (rid = its a11y region id), the caret / hit-test geometry is the
    /// nested frame's (inside the nested rect), typing edits the nested
    /// story only (both boxes go dirty for the writer), a press on the
    /// outer story switches to it, and the edit survives save + reload.
    #[test]
    fn clicking_a_nested_text_box_enters_and_edits_its_story() {
        let mut engine = test_engine_with_doc(nested_text_box_doc());
        let (outer, inner) = nested_box_rects(&engine);
        let inside = |b: BoxRect, x: f32, y: f32| {
            x >= b.0 - 0.5 && x <= b.0 + b.2 + 0.5 && y >= b.1 - 0.5 && y <= b.1 + b.3 + 0.5
        };
        let evt = engine.do_place_caret_at_point(
            0,
            BridgePoint {
                x: inner.0 + inner.2 / 2.0,
                y: inner.1 + inner.3 / 3.0,
            },
        );
        let Event::SelectionChanged { editing_story, .. } = &evt else {
            panic!("{evt:?}");
        };
        let story = editing_story.as_ref().expect("a story is active");
        assert_eq!(story.area, bridge::HeaderFooterArea::TextBox);
        assert_eq!(story.rid, "0@0/0@0", "the nested region's a11y id");
        assert!(matches!(
            &engine.active_story,
            StoryTarget::TextBox { host, at: 0, inner: Some((ih, 0)), .. }
                if *host == EngineBlockPath::top(0) && *ih == EngineBlockPath::top(0)
        ));
        let caret = engine.selection.as_ref().unwrap().caret.clone();
        assert_eq!(caret.path.steps, vec![BridgePathStep::Block { idx: 0 }]);
        /* The press hit-tests the NESTED story's line: mid-box lands
        mid-"Inner story". */
        assert!(
            caret.offset > 0 && caret.offset < "Inner story".len() as u32,
            "{caret:?}"
        );
        /* Caret geometry is the nested story's line, inside the nested
        box. */
        let geom = engine.document_geometry().expect("nested geometry");
        assert_eq!(geom.len(), 1, "one nested story line");
        let line = &geom[0];
        assert_eq!(line.end_byte, "Inner story".len() as u32);
        assert!(inside(inner, line.hit_left, line.y_top));
        assert!(inside(inner, line.hit_left + line.hit_width, line.y_top));

        engine.do_set_selection(
            BridgeLogicalRange {
                start: bpos_top(0, 0),
                end: bpos_top(0, 0),
            },
            bpos_top(0, 0),
        );
        let typed = engine.do_insert_text_interactive(bpos_top(0, 0), "typed ".to_string());
        assert!(matches!(typed, Event::SelectionChanged { .. }), "{typed:?}");
        assert_eq!(nested_story_text(&engine), "typed Inner story");
        let doc = engine.undo.current();
        let outer_story = doc
            .text_box_at(&EngineBlockPath::top(0), 0)
            .expect("outer story");
        assert!(outer_story.dirty, "the outer container regenerates");
        assert!(
            outer_story.body[0]
                .as_paragraph()
                .is_some_and(|p| p.text.contains("Outer story text")),
            "the outer story text is untouched"
        );
        /* The caret stays in the nested story, after the typed text. */
        let caret = engine.selection.as_ref().unwrap().caret.clone();
        assert_eq!(caret.offset, "typed ".len() as u32);

        /* A press on the outer story (below the nested box) switches to
        it; a press back in the nested box re-enters it. */
        let evt = engine.do_place_caret_at_point(
            0,
            BridgePoint {
                x: outer.0 + outer.2 - 12.0,
                y: outer.1 + outer.3 - 12.0,
            },
        );
        let Event::SelectionChanged { editing_story, .. } = &evt else {
            panic!("{evt:?}");
        };
        assert_eq!(editing_story.as_ref().map(|s| s.rid.as_str()), Some("0@0"));
        assert!(matches!(
            &engine.active_story,
            StoryTarget::TextBox { inner: None, .. }
        ));
        let (_, inner) = nested_box_rects(&engine);
        engine.do_place_caret_at_point(
            0,
            BridgePoint {
                x: inner.0 + inner.2 / 2.0,
                y: inner.1 + inner.3 / 3.0,
            },
        );
        assert!(matches!(
            &engine.active_story,
            StoryTarget::TextBox { inner: Some(_), .. }
        ));

        /* Undo the keystroke: the nested story stays active, clamped. */
        let evt = engine.do_undo();
        assert!(!matches!(evt, Event::Error { .. }), "{evt:?}");
        assert!(matches!(
            &engine.active_story,
            StoryTarget::TextBox { inner: Some(_), .. }
        ));
        assert_eq!(nested_story_text(&engine), "Inner story");
        let _ = engine.do_redo();
        assert_eq!(nested_story_text(&engine), "typed Inner story");

        /* Save → reload: the nested edit round-trips. */
        let _ = engine.do_exit_header_footer();
        let Event::DocumentSaved { bytes, .. } = engine.save_docx_bytes("test") else {
            panic!("save");
        };
        let back = format_docx::read_docx(&bytes).expect("re-read");
        let outer_back = back
            .document
            .text_box_at(&EngineBlockPath::top(0), 0)
            .expect("outer box re-reads");
        let nested_back = DocumentTree::from_blocks(outer_back.body.clone())
            .text_box_at(&EngineBlockPath::top(0), 0)
            .map(|s| s.body[0].as_paragraph().map(|p| p.text.clone()));
        assert_eq!(nested_back.flatten().as_deref(), Some("typed Inner story"));
    }

    /// Issue #196 — the IME preview renders inside the ACTIVE nested
    /// story only (not the outer story, not the body).
    #[test]
    fn ime_preview_renders_inside_the_active_nested_text_box() {
        let mut engine = test_engine_with_doc(nested_text_box_doc());
        let (_, inner) = nested_box_rects(&engine);
        engine.do_place_caret_at_point(
            0,
            BridgePoint {
                x: inner.0 + inner.2 / 2.0,
                y: inner.1 + inner.3 / 3.0,
            },
        );
        assert!(matches!(
            &engine.active_story,
            StoryTarget::TextBox { inner: Some(_), .. }
        ));
        let glyphs = |blocks: &[LayoutBlock]| -> usize {
            blocks
                .iter()
                .filter_map(LayoutBlock::as_paragraph)
                .flat_map(|p| p.lines.iter())
                .flat_map(|l| l.runs.iter())
                .map(|r| r.glyphs.len())
                .sum()
        };
        let (pages, ..) = engine
            .build_pages(engine.scale(), true, None)
            .expect("layout");
        let otb = pages[0].floats[0].text_box.as_deref().expect("outer");
        let (outer_before, inner_before) = (
            glyphs(&otb.blocks),
            glyphs(&otb.floats[0].text_box.as_deref().expect("nested").blocks),
        );
        engine.composition = Some(CompositionState {
            at: bpos_top(0, 0),
            text: "ime".to_string(),
        });
        let (pages, ..) = engine
            .build_pages(engine.scale(), true, None)
            .expect("layout");
        let otb = pages[0].floats[0].text_box.as_deref().expect("outer");
        let itb = otb.floats[0].text_box.as_deref().expect("nested");
        assert_eq!(
            glyphs(&itb.blocks),
            inner_before + 3,
            "preview in the nested story"
        );
        assert_eq!(glyphs(&otb.blocks), outer_before, "outer story untouched");
    }

    /// Issue #196 — the nesting cap bounds hit-testing too: a box nested
    /// past level two is not laid out, so a press over where it would be
    /// enters the level-two story, never a third level.
    #[test]
    fn nested_hit_testing_stops_at_the_nesting_cap() {
        let mut doc = nested_text_box_doc();
        if let Some(engine::Block::Paragraph(p)) = doc.blocks.get_mut(0)
            && let engine::InlineKind::TextBox { story, .. } = &mut p.inline_objects[0].kind
            && let Some(engine::Block::Paragraph(sp)) = story.body.get_mut(0)
            && let engine::InlineKind::TextBox { story: inner, .. } = &mut sp.inline_objects[0].kind
        {
            let third = DocumentTree::from_blocks(vec![plain_para("level two")]);
            let (third, _, _) = third.insert_text_box_at(
                EnginePos {
                    path: EngineBlockPath::top(0),
                    offset: 0,
                },
                300_000,
                200_000,
            );
            inner.body = third.blocks.iter().cloned().collect();
        } else {
            panic!("fixture shape");
        }
        let mut engine = test_engine_with_doc(doc);
        let (_, inner) = nested_box_rects(&engine);
        engine.do_place_caret_at_point(
            0,
            BridgePoint {
                x: inner.0 + 4.0,
                y: inner.1 + 4.0,
            },
        );
        assert!(matches!(
            &engine.active_story,
            StoryTarget::TextBox { inner: Some(_), .. }
        ));
    }

    /// Issue #197 — a picture in a NESTED box's story (level two) resolves
    /// too: the nesting cap bounds box recursion, not pictures.
    #[test]
    fn floating_picture_in_nested_box_story_resolves() {
        let mut doc = nested_text_box_doc();
        if let Some(engine::Block::Paragraph(p)) = doc.blocks.get_mut(0)
            && let engine::InlineKind::TextBox { story, .. } = &mut p.inline_objects[0].kind
            && let Some(engine::Block::Paragraph(sp)) = story.body.get_mut(0)
            && let engine::InlineKind::TextBox { story: inner, .. } = &mut sp.inline_objects[0].kind
        {
            let mut level2 = DocumentTree::from_text("\u{FFFC}pic");
            if let Some(ip) = level2.blocks[0].as_paragraph_mut() {
                ip.inline_objects.push(story_float_image("rIdInnerPic"));
            }
            inner.body = level2.blocks.iter().cloned().collect();
        } else {
            panic!("fixture shape");
        }
        let engine = test_engine_with_doc(doc);
        let (pages, _, _, info) = engine.build_pages(1.0, false, None).expect("layout");
        assert!(info.degradations.is_empty(), "{:?}", info.degradations);
        let otb = pages[0].floats[0].text_box.as_deref().expect("outer");
        let itb = otb.floats[0].text_box.as_deref().expect("nested");
        assert_eq!(itb.floats.len(), 1);
        assert_eq!(itb.floats[0].rel_id, "rIdInnerPic");
        let scene = render::scene::build_document_scene(&pages, 0.0);
        assert!(scene.cmds.iter().any(|c| matches!(
            c,
            render::scene::DisplayCmd::DrawImage { rel_id, .. } if rel_id == "rIdInnerPic"
        )));
    }

    /// A box nested past the layout cap (only a hand-built tree can carry
    /// one) keeps its place in its parent story but is not resolved —
    /// the recursion is bounded and nothing degrades.
    #[test]
    fn text_box_nesting_past_the_cap_is_not_laid_out() {
        let mut doc = nested_text_box_doc();
        /* Nest a third level inside "Inner". */
        if let Some(engine::Block::Paragraph(p)) = doc.blocks.get_mut(0)
            && let engine::InlineKind::TextBox { story, .. } = &mut p.inline_objects[0].kind
            && let Some(engine::Block::Paragraph(sp)) = story.body.get_mut(0)
            && let engine::InlineKind::TextBox { story: inner, .. } = &mut sp.inline_objects[0].kind
        {
            let third = DocumentTree::from_blocks(vec![plain_para("level two")]);
            let (third, _, _) = third.insert_text_box_at(
                EnginePos {
                    path: EngineBlockPath::top(0),
                    offset: 0,
                },
                300_000,
                200_000,
            );
            inner.body = third.blocks.iter().cloned().collect();
        } else {
            panic!("fixture shape");
        }
        let engine = test_engine_with_doc(doc);
        let (pages, _, _, info) = engine.build_pages(1.0, false, None).expect("layout");
        assert!(info.degradations.is_empty());
        let otb = pages[0].floats[0].text_box.as_deref().expect("outer");
        let itb = otb.floats[0].text_box.as_deref().expect("nested");
        assert!(itb.floats.is_empty(), "level three is past the cap");
        assert!(!itb.blocks.is_empty(), "level two still lays out its story");
    }

    fn a11y_text(nodes: &[A11yNode]) -> Vec<String> {
        nodes
            .iter()
            .map(|n| match n {
                A11yNode::Paragraph(p) => p.runs.iter().map(|r| r.text.as_str()).collect(),
                A11yNode::TextBox(b) => format!("[box {}]", b.id),
                A11yNode::Table(_) => "[table]".to_string(),
                A11yNode::Story(_) => "[story]".to_string(),
            })
            .collect()
    }

    /// The a11y tree mirrors every text box as a `TextBox` region right
    /// after its anchor paragraph — named from `docPr`, holding the
    /// body's exact paragraph shape — and a nested box inside its
    /// parent's region after ITS anchor paragraph.
    #[test]
    fn a11y_tree_emits_text_box_regions_after_their_anchor_paragraphs() {
        let engine = test_engine_with_doc(nested_text_box_doc());
        let nodes = engine.build_a11y_nodes();
        assert_eq!(nodes.len(), 3, "{:?}", a11y_text(&nodes));
        assert!(matches!(nodes[0], A11yNode::Paragraph(_)));
        assert!(matches!(nodes[2], A11yNode::Paragraph(_)));
        let A11yNode::TextBox(outer) = &nodes[1] else {
            panic!("region after the anchor paragraph: {:?}", nodes[1]);
        };
        assert_eq!(outer.id, "0@0");
        assert_eq!(outer.name.as_deref(), Some("Sidebar"));
        assert_eq!(outer.description.as_deref(), Some("Pull quote & notes"));
        assert_eq!(outer.nodes.len(), 2);
        let A11yNode::Paragraph(op) = &outer.nodes[0] else {
            panic!("outer story paragraph");
        };
        assert!(op.runs.iter().any(|r| r.text.contains("Outer story text")));
        let A11yNode::TextBox(inner) = &outer.nodes[1] else {
            panic!("nested region after its anchor paragraph");
        };
        assert_eq!(inner.id, "0@0/0@0");
        assert_eq!(inner.name.as_deref(), Some("Inner"));
        assert_eq!(inner.description, None);
        assert_eq!(a11y_text(&inner.nodes), ["Inner story"]);

        /* Two sibling boxes in the #83 fixture: one region per anchor
        paragraph, ids matching the story rid scheme, RTL text intact. */
        let engine = test_engine_with_doc(text_box_doc());
        let nodes = engine.build_a11y_nodes();
        let got = a11y_text(&nodes);
        assert_eq!(got.len(), 4, "{got:?}");
        assert_eq!(got[1], "[box 0@0]");
        assert_eq!(got[3], "[box 1@0]");
        let A11yNode::TextBox(rtl) = &nodes[3] else {
            panic!("rtl region");
        };
        assert_eq!(a11y_text(&rtl.nodes), ["صندوق نص من اليمين"]);
    }

    /// Documents without text boxes keep their pre-#165 a11y shape: one
    /// node per top-level block, cells unchanged.
    #[test]
    fn a11y_tree_without_text_boxes_is_unchanged() {
        let engine = test_engine_with_doc(DocumentTree::from_blocks(vec![
            plain_para("one"),
            plain_para("two"),
        ]));
        let nodes = engine.build_a11y_nodes();
        assert_eq!(a11y_text(&nodes), ["one", "two"]);
    }

    /// Typing inside a text box patches ONLY that box's region — one
    /// `Update` at the region's index — never a full-tree `Replace`; the
    /// enter announcement names the region.
    #[test]
    fn a11y_delta_for_a_text_box_edit_patches_only_its_region() {
        let mut engine = test_engine_with_doc(nested_text_box_doc());
        let first = engine.build_a11y_delta();
        assert!(matches!(first.as_slice(), [A11yPatch::Replace { .. }]));
        engine.pending_announcements.clear();
        engine.enter_text_box_story(EngineBlockPath::top(0), 0, None, 0, 0);
        assert!(
            engine
                .pending_announcements
                .iter()
                .any(|(_, m)| m == "Editing text box: Sidebar"),
            "{:?}",
            engine.pending_announcements
        );
        let caret = engine.selection.as_ref().unwrap().caret.clone();
        let typed = engine.do_insert_text_interactive(caret, "Hello ".to_string());
        assert!(matches!(typed, Event::SelectionChanged { .. }), "{typed:?}");
        let delta = engine.build_a11y_delta();
        assert_eq!(delta.len(), 1, "{delta:?}");
        let A11yPatch::Update {
            index,
            node: A11yNode::TextBox(region),
        } = &delta[0]
        else {
            panic!("expected a region Update, got {delta:?}");
        };
        assert_eq!(*index, 1);
        assert_eq!(region.id, "0@0");
        let A11yNode::Paragraph(p) = &region.nodes[0] else {
            panic!("story paragraph");
        };
        assert!(p.runs[0].text.starts_with("Hello "));
    }

    /// `Command::SetImageWrap` switches the mode (one undo step), the
    /// behind / in-front modes stop cutting text, the image rect reports
    /// the new mode, and an inline image is an honest error.
    #[test]
    fn set_image_wrap_dispatch_switches_modes_and_rejects_inline() {
        let mut engine = test_engine_with_doc(wrapped_image_doc(
            engine::WrapKind::None,
            engine::VRelativeFrom::Paragraph,
        ));
        let cut = |e: &Engine| {
            let (pages, ..) = e.build_pages(2.0, false, None).expect("layout");
            pages[0].blocks[0]
                .as_paragraph()
                .expect("paragraph")
                .lines
                .iter()
                .any(|l| !l.segments.is_empty())
        };
        assert!(!cut(&engine), "in front of text cuts nothing");
        assert_eq!(
            engine.image_geometry().expect("g")[0].wrap,
            Some(bridge::ImageWrapMode::InFrontOfText)
        );
        for (mode, cuts) in [
            (bridge::ImageWrapMode::Square, true),
            (bridge::ImageWrapMode::Tight, true),
            (bridge::ImageWrapMode::Through, true),
            (bridge::ImageWrapMode::TopAndBottom, true),
            (bridge::ImageWrapMode::BehindText, false),
            (bridge::ImageWrapMode::InFrontOfText, false),
        ] {
            let evt = engine.do_set_image_wrap(BridgeBlockPath::top(0), 0, mode);
            assert!(matches!(evt, Event::SelectionChanged { .. }), "{evt:?}");
            assert_eq!(engine.image_geometry().expect("g")[0].wrap, Some(mode));
            /* Top-and-bottom skips whole bands: no segments, but the text
            below the image moved down. */
            let segmented = cut(&engine);
            match mode {
                bridge::ImageWrapMode::TopAndBottom => assert!(!segmented),
                _ => assert_eq!(segmented, cuts, "{mode:?}"),
            }
        }
        let evt = engine.do_undo();
        assert!(matches!(evt, Event::SelectionChanged { .. }));
        assert_eq!(
            engine.image_geometry().expect("g")[0].wrap,
            Some(bridge::ImageWrapMode::BehindText),
            "undo is one step"
        );
        let mut inline = test_engine_with_doc(inline_image_doc());
        let evt =
            inline.do_set_image_wrap(BridgeBlockPath::top(0), 0, bridge::ImageWrapMode::Square);
        assert!(matches!(evt, Event::Error { .. }), "{evt:?}");
    }

    /// Top-and-bottom wrap moves the text under the image down past it.
    #[test]
    fn top_and_bottom_wrap_pushes_following_lines_below_the_image() {
        let plain = test_engine_with_doc(wrapped_image_doc(
            engine::WrapKind::None,
            engine::VRelativeFrom::Paragraph,
        ));
        let tb = test_engine_with_doc(wrapped_image_doc(
            engine::WrapKind::TopAndBottom,
            engine::VRelativeFrom::Paragraph,
        ));
        let h = |e: &Engine| {
            let (pages, ..) = e.build_pages(2.0, false, None).expect("layout");
            pages[0].blocks[0].as_paragraph().expect("p").size.height
        };
        let img_h = engine::emu_to_pt(457_200) * 2.0;
        assert!(
            h(&tb) >= h(&plain) + img_h * 0.9,
            "{} vs {}",
            h(&tb),
            h(&plain)
        );
    }

    /// The oscillation #82 names: a top-and-bottom image positioned
    /// against its own anchor LINE pushes that line below itself, then
    /// follows it. The wrap loop must terminate within its caps, report
    /// the escape on the paint's degradation notes, and drop no text.
    #[test]
    fn image_that_pushes_its_own_anchor_terminates_and_reports() {
        let engine = test_engine_with_doc(wrapped_image_doc(
            engine::WrapKind::TopAndBottom,
            engine::VRelativeFrom::Line,
        ));
        let started = std::time::Instant::now();
        let (pages, _, _, info) = engine.build_pages(2.0, false, None).expect("layout");
        assert!(started.elapsed() < adversarial_budget() * 4);
        assert!(
            info.degradations.iter().any(|d| matches!(
                d.reason,
                LayoutDegradeReason::WrapObjectFrozen | LayoutDegradeReason::WrapOscillation
            )),
            "{:?}",
            info.degradations
        );
        let text_len = engine.undo.current().blocks[0]
            .as_paragraph()
            .expect("p")
            .text
            .len() as u32;
        let laid: u32 = pages
            .iter()
            .flat_map(|p| p.blocks.iter())
            .filter_map(LayoutBlock::as_paragraph)
            .flat_map(|p| p.lines.iter())
            .flat_map(|l| l.runs.iter())
            .map(|r| r.source_range.end - r.source_range.start)
            .sum();
        assert!(laid + 8 >= text_len, "{laid} of {text_len} bytes laid out");
    }

    /// No wrap yet: a floating image's sentinel reserves no width and grows
    /// no line — the caret geometry of "a\u{FFFC}b"+float equals "ab"'s,
    /// while the SAME image inline widens the line (so the test
    /// discriminates).
    #[test]
    fn floating_image_leaves_text_geometry_unchanged() {
        let plain = test_engine_with_doc(DocumentTree::from_text("ab"));
        let floated = test_engine_with_doc(floating_image_doc(engine::FloatAnchor::default()));
        let g0 = plain.document_geometry().expect("geom");
        let g1 = floated.document_geometry().expect("geom");
        assert_eq!(g0.len(), 1);
        assert_eq!(g1.len(), 1);
        assert_eq!(g0[0].height, g1[0].height, "the line does not grow");
        let end = |g: &LineGeom| g.slots.iter().map(|s| s.x).fold(f32::MIN, f32::max);
        assert!(
            (end(&g0[0]) - end(&g1[0])).abs() < 0.01,
            "line end unchanged: {} vs {}",
            end(&g0[0]),
            end(&g1[0])
        );
        let mut inline_doc = DocumentTree::from_text("a\u{FFFC}b");
        if let Some(p) = inline_doc.blocks[0].as_paragraph_mut() {
            p.inline_objects.push(engine::InlineObject {
                at: 1,
                kind: engine::InlineKind::Image {
                    rel_id: "nge_img_1".to_string(),
                    width_emu: 914_400,
                    height_emu: 457_200,
                },
                anchor: None,
                source_xml: None,
            });
        }
        let inline = test_engine_with_doc(inline_doc);
        let g2 = inline.document_geometry().expect("geom");
        assert!(
            end(&g2[0]) > end(&g0[0]) + 10.0,
            "the inline image DOES widen the line"
        );
    }

    #[test]
    fn insert_section_break_dispatch_reports_two_sections() {
        /* Phase 3 (#40) — end-to-end through the command handler: the
        break lands, the caret moves into the second section, and
        SelectionChanged's section_geometry carries index 1 of 2. */
        let doc = DocumentTree::from_text("hello world");
        let mut engine = test_engine_with_doc(doc);
        let evt = engine.do_insert_section_break(bpos_top(0, 5), SectionBreakKind::NextPage);
        let Event::SelectionChanged {
            caret: _,
            section_geometry: Some(geom),
            ..
        } = evt
        else {
            panic!("expected SelectionChanged with section_geometry, got {evt:?}");
        };
        assert_eq!(geom.section_count, 2);
        assert_eq!(geom.section_index, 1, "caret starts the second section");
        assert_eq!(engine.undo.current().effective_sections().len(), 2);
        /* One undo entry reverts the whole break. */
        assert!(engine.undo.can_undo());
        let _ = engine.undo.undo();
        assert_eq!(engine.undo.current().effective_sections().len(), 1);
    }

